# ==============================================================================# 064_MODULE_GRAPH.py# IOTEC MISSION CONTROL# MODULE GRAPH# ==============================================================================from pathlib import Pathimport sqlite3DB = Path("mission_control.db")class ModuleGraph:    def __init__(self):        self.conn = sqlite3.connect(DB, timeout=30)        self.conn.row_factory = sqlite3.Row        self.conn.execute("PRAGMA journal_mode=WAL")        self.conn.execute("PRAGMA busy_timeout=30000")        self.cur = self.conn.cursor()    # ------------------------------------------------------------------    def total_modules(self):        self.cur.execute("""            SELECT COUNT(*)            FROM modules        """)        return self.cur.fetchone()[0]    # ------------------------------------------------------------------    def total_dependencies(self):        self.cur.execute("""            SELECT COUNT(*)            FROM module_dependencies        """)        return self.cur.fetchone()[0]    # ------------------------------------------------------------------    def modules_without_dependencies(self):        self.cur.execute("""        SELECT module_name        FROM modules        WHERE module_name NOT IN(            SELECT DISTINCT module_name            FROM module_dependencies        )        ORDER BY module_name        """)        return self.cur.fetchall()    # ------------------------------------------------------------------    def most_dependent_modules(self, limit=30):        self.cur.execute("""        SELECT            module_name,            COUNT(*) total        FROM module_dependencies        GROUP BY module_name        ORDER BY total DESC        LIMIT ?        """, (limit,))        return self.cur.fetchall()    # ------------------------------------------------------------------    def most_used_dependencies(self, limit=30):        self.cur.execute("""        SELECT            dependency,            COUNT(*) total        FROM module_dependencies        GROUP BY dependency        ORDER BY total DESC        LIMIT ?        """, (limit,))        return self.cur.fetchall()    # ------------------------------------------------------------------    def dependency_tree(self, module):        self.cur.execute("""        SELECT            dependency,            dependency_type        FROM module_dependencies        WHERE module_name=?        ORDER BY dependency        """, (module,))        return self.cur.fetchall()    # ------------------------------------------------------------------    def graph_statistics(self):        total_modules = self.total_modules()        total_dependencies = self.total_dependencies()        orphan_modules = len(self.modules_without_dependencies())        connected = total_modules - orphan_modules        return {            "modules": total_modules,            "dependencies": total_dependencies,            "connected": connected,            "orphans": orphan_modules        }# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    graph = ModuleGraph()    stats = graph.graph_statistics()    print("=" * 70)    print("MODULE GRAPH")    print("=" * 70)    print(f"Módulos.............: {stats['modules']}")    print(f"Dependências........: {stats['dependencies']}")    print(f"Módulos conectados..: {stats['connected']}")    print(f"Módulos órfãos......: {stats['orphans']}")    print("=" * 70)    print("TOP MÓDULOS MAIS DEPENDENTES")    print("=" * 70)    for item in graph.most_dependent_modules():        print(            item["module_name"].ljust(45),            item["total"]        )    print("=" * 70)    print("DEPENDÊNCIAS MAIS UTILIZADAS")    print("=" * 70)    for item in graph.most_used_dependencies():        print(            item["dependency"].ljust(35),            item["total"]        )